module.exports = function (RED) {
    "use strict";

    function EventSourceNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        this.on("input", function (msg, send, done) {
            send(msg);
            if (done) done();
        });
    }

    RED.nodes.registerType("EventSource", EventSourceNode);
};